import { motion, AnimatePresence, cubicBezier } from 'framer-motion'
import { useMemo, useState, useEffect } from 'react'
import { ArrowRight, Expand, X } from 'lucide-react'

// Updated static data using Unsplash for theme-relevant images.
const galleryItems = [
  // --- Conference Category ---
  { 
    id: 1, 
    src: 'data:image/jpeg;base64,', 
    alt: 'Speaker on stage at the AI Innovations Summit', 
    category: 'Conference', 
    title: 'AI Innovations Summit' 
  },
  { 
    id: 4, 
    src: 'https://event.ru/wp-content/uploads/2024/07/w_ZFYSZQd4k-600x315.jpg', 
    alt: 'Keynote speaker addressing a large audience at a tech forum', 
    category: 'Conference', 
    title: 'Global Tech Forum' 
  },
  { 
    id: 7, 
    src: 'data:image/jpeg;base64,', 
    alt: 'Professionals networking during a conference break', 
    category: 'Conference', 
    title: 'Networking Mixer' 
  },
  
  // --- Webinar Category ---
  { 
    id: 2, 
    src: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRwE0wXOeZYguH7R_aUPKHuiKKX5dk6Xzx7DRgI0Ktt9WVJgZ68MhhcqZucbmNglxFRiHw&usqp=CAU', 
    alt: 'Presenter sharing a screen during a webinar on automation', 
    category: 'Webinar', 
    title: 'The Future of Automation' 
  },
  { 
    id: 6, 
    src: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRDk6RPyC1OERUSefz7V-jmg7nY2w_nB5Vo6A&s', 
    alt: 'Attendees in a virtual meeting grid view for a masterclass', 
    category: 'Webinar', 
    title: 'Remote Work Masterclass' 
  },
  { 
    id: 9, 
    src: 'data:image/jpeg;base64,', 
    alt: 'Dashboard showing data analytics during a webinar', 
    category: 'Webinar', 
    title: 'Data-Driven Decisions' 
  },

  // --- Team Category ---
  { 
    id: 3, 
    src: 'data:image/jpeg;base64,', 
    alt: 'Team collaborating around a whiteboard during a strategy session', 
    category: 'Team', 
    title: 'Strategy Workshop Session' 
  },
  { 
    id: 5, 
    src: 'data:image/jpeg;base64,', 
    alt: 'Modern office interior with our team working collaboratively', 
    category: 'Team', 
    title: 'Our Collaborative Workspace' 
  },
  { 
    id: 8, 
    src: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR_K5Vxvp0hQfa2voYMeqKW471bxtRqx0h-zg&s', 
    alt: 'Developers focused on their laptops during a hackathon', 
    category: 'Team', 
    title: 'Hackathon in Progress' 
  },
  { 
    id: 10, 
    src: 'data:image/jpeg;base64,', 
    alt: 'Team celebrating a successful product launch', 
    category: 'Team', 
    title: 'Product Launch Day' 
  },
];


const categories = ['All', 'Conference', 'Webinar', 'Team']

export default function Gallery() {
  const [filter, setFilter] = useState('All')
  const [selectedImg, setSelectedImg] = useState<string | null>(null)

  const filteredItems = useMemo(() => {
    if (filter === 'All') return galleryItems
    return galleryItems.filter((item) => item.category === filter)
  }, [filter])
  
  const fadeUp = useMemo(() => ({
    hidden: { opacity: 0, y: 32 },
    show: { opacity: 1, y: 0, transition: { duration: 0.8, ease: cubicBezier(0.22, 1, 0.36, 1) } },
  }), [])

  const stagger = useMemo(() => ({
    hidden: {},
    show: { transition: { staggerChildren: 0.1 } },
  }), [])
  
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setSelectedImg(null)
      }
    }
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [])

  return (
    <PageShell>
      {/* Hero Section */}
      <motion.section 
        variants={fadeUp}
        initial="hidden"
        animate="show"
        className="text-center"
      >
        <h1 className="mb-4 text-3xl font-bold sm:text-4xl md:text-5xl text-slate-900 dark:text-slate-100 sm:mb-6">
          Our Work in Pictures
        </h1>
        <p className="max-w-3xl px-4 mx-auto text-lg sm:text-xl text-slate-600 dark:text-slate-300">
          A glimpse into our events, team culture, and the innovative solutions we build.
        </p>
      </motion.section>

      {/* Filter Tabs */}
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.2, duration: 0.8 }}
        className="flex flex-wrap justify-center gap-2 my-8 sm:gap-4 sm:my-12"
      >
        {categories.map((cat) => (
          <button
            key={cat}
            onClick={() => setFilter(cat)}
            className={`px-4 sm:px-6 py-2 sm:py-2.5 rounded-full text-sm sm:text-base font-medium transition-all duration-300 ${
              filter === cat
                ? 'bg-primary-600 text-white shadow-md'
                : 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 hover:bg-slate-200 dark:hover:bg-slate-700'
            }`}
          >
            {cat}
          </button>
        ))}
      </motion.div>

      {/* Image Grid */}
      <motion.div
        variants={stagger}
        initial="hidden"
        animate="show"
        className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 sm:gap-8"
      >
        <AnimatePresence>
          {filteredItems.map((item) => (
            <motion.div
              key={item.id}
              variants={fadeUp}
              layout
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.8 }}
              transition={{ duration: 0.4, ease: 'easeInOut' }}
              onClick={() => setSelectedImg(item.src)}
              className="relative overflow-hidden cursor-pointer card-premium aspect-video rounded-2xl group"
            >
              <img 
                src={item.src} 
                alt={item.alt} 
                className="object-cover w-full h-full transition-transform duration-500 ease-in-out group-hover:scale-110" 
              />
              <div className="absolute inset-0 transition-opacity duration-300 opacity-0 bg-gradient-to-t from-black/60 via-black/20 to-transparent group-hover:opacity-100"></div>
              <div className="absolute bottom-0 left-0 p-4 text-white transition-all duration-300 transform translate-y-4 opacity-0 sm:p-5 group-hover:translate-y-0 group-hover:opacity-100">
                <h3 className="text-base font-bold sm:text-lg">{item.title}</h3>
                <p className="text-xs sm:text-sm opacity-80">{item.category}</p>
              </div>
              <div className="absolute p-2 transition-all duration-300 transform scale-50 rounded-full opacity-0 top-4 right-4 bg-white/20 backdrop-blur-sm group-hover:scale-100 group-hover:opacity-100">
                  <Expand className="text-white size-5" />
              </div>
            </motion.div>
          ))}
        </AnimatePresence>
      </motion.div>

      {/* Lightbox Modal */}
      <AnimatePresence>
        {selectedImg && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setSelectedImg(null)}
            className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm"
          >
            <motion.img
              src={selectedImg}
              alt="Enlarged view"
              className="max-w-full max-h-[90vh] object-contain rounded-lg shadow-2xl"
              onClick={(e) => e.stopPropagation()} 
            />
            <button
              onClick={() => setSelectedImg(null)}
              className="absolute p-2 text-white transition-colors rounded-full top-4 right-4 bg-white/10 hover:bg-white/20"
              aria-label="Close image viewer"
            >
              <X className="size-6" />
            </button>
          </motion.div>
        )}
      </AnimatePresence>

      {/* CTA Section */}
      <motion.section 
        initial={{ opacity: 0, y: 32 }} 
        whileInView={{ opacity: 1, y: 0 }} 
        transition={{ duration: 0.8 }} 
        viewport={{ once: true }} 
        className="mt-20"
      >
        <div className="relative p-8 overflow-hidden text-center card-premium sm:p-12">
          <div className="absolute inset-0 bg-gradient-to-br from-primary-500/5 via-transparent to-accent-500/5"></div>
          <div className="relative z-10">
            <h2 className="mb-4 text-3xl font-bold sm:text-4xl md:text-5xl text-slate-900 dark:text-slate-100 sm:mb-6">
              Inspired by Our Work?
            </h2>
            <p className="max-w-2xl px-4 mx-auto mb-6 text-lg sm:text-xl text-slate-600 dark:text-slate-300 sm:mb-8">
              Let's discuss how AI-Solutions can help transform your organization and achieve similar results.
            </p>
            <div className="flex flex-col justify-center gap-4 sm:flex-row">
              <a 
                className="w-full px-6 py-3 text-base btn-primary sm:text-lg sm:px-8 sm:py-4 group sm:w-auto" 
                href="/schedule-demo"
              >
                Schedule a Demo
                <ArrowRight className="ml-2 transition-transform duration-200 size-4 sm:size-5 group-hover:translate-x-1" />
              </a>
              <a 
                className="w-full px-6 py-3 text-base btn-outline sm:text-lg sm:px-8 sm:py-4 sm:w-auto" 
                href="/solutions"
              >
                Explore Solutions
              </a>
            </div>
          </div>
        </div>
      </motion.section>
    </PageShell>
  )
}